    "<strong style=\"color:var(--gold)\">⚡追込練習</strong><br>成長が大きく伸びる代わりに体調の消耗が激しく、怪我のリスクも上がります。<br><br>体調50以上・最大2週連続まで。": "<strong style=\"color:var(--gold)\">⚡ Hard Training</strong><br>Growth jumps, but condition drains fast and the injury risk climbs.<br><br>Requires condition 50 or above, two consecutive weeks at most.",
    "<strong style=\"color:var(--gold)\">おまかせ編成</strong><br>・🔥おすすめ — 因縁・鮮度・話題性を考慮した最適カード<br>・💪OVR順 — 実力上位同士をマッチング<br>・🎤集客力順 — 集客力の高い選手をメインに": "<strong style=\"color:var(--gold)\">Auto Booking</strong><br>• 🔥 Recommended — the best card, weighing grudges, freshness and buzz<br>• 💪 By OVR — the strongest against the strongest<br>• 🎤 By Draw — puts your biggest draws on top",
    "<strong style=\"color:var(--gold)\">育成方針</strong><br>・<strong>バランス</strong> — 興行週はプロモ、練習週は練習。迷ったらこれ<br>・<strong>練習優先</strong> — ステータス成長に集中<br>・<strong>プロモ優先</strong> — 人気を上げる(上限あり)<br>・<strong>休養重視</strong> — 確実に休ませる<br><br>どの方針でも、体調60未満になると自動で休養します。": "<strong style=\"color:var(--gold)\">Training Policy</strong><br>• <strong>Balanced</strong> — promo on show weeks, training on practice weeks. The safe default<br>• <strong>Training First</strong> — concentrates on stat growth<br>• <strong>Promo First</strong> — raises popularity (up to a ceiling)<br>• <strong>Rest First</strong> — guarantees time off<br><br>Under any policy, a wrestler rests automatically once her condition falls below 60.",
    "<strong style=\"color:var(--gold)\">🏛️ 地域振興助成金</strong><br>\r\n現在の支給額: <strong style=\"color:#2ecc71\">+{subsidyAmt}万/週</strong>（自動）<br>\r\n<span style=\"color:#aaa\">人気があと<strong style=\"color:#fff\">{remaining}pt</strong>上がると打ち切り</span><br><br>\r\n<span style=\"color:#aaa;font-size:11px\">打ち切り後はスポンサー収入が<br>10万 → <strong style=\"color:#fff\">30万/週</strong>に増えます</span>": "<strong style=\"color:var(--gold)\">🏛️ Regional Development Grant</strong><br>\r\nCurrent payment: <strong style=\"color:#2ecc71\">+¥{subsidyAmt:man}/week</strong> (automatic)<br>\r\n<span style=\"color:#aaa\">Ends once popularity rises another <strong style=\"color:#fff\">{remaining}pt</strong></span><br><br>\r\n<span style=\"color:#aaa;font-size:11px\">After it ends, sponsor income rises from<br>¥100k to <strong style=\"color:#fff\">¥300k/week</strong></span>",
    "<strong style=\"color:var(--gold)\">🤖 おまかせ</strong><br>体調80未満の選手を休養にし、体調80以上で休養方針の選手をバランスに戻します。それ以外の方針は維持されます。": "<strong style=\"color:var(--gold)\">🤖 Auto</strong><br>Puts anyone below condition 80 on rest, and brings anyone at 80 or above back from rest to balanced. Every other policy is left alone.",
