    "{epithet}{name}が現役を退き、{org}の殿堂にその名を刻んだ。{seasons}シーズンにわたる歩みは、ひとりの選手の経歴にとどまらず、団体そのものの歴史の一部となった。｜{recordLine}｜リングを去っても、その試合、その言葉、その背中は記録と記憶の中に残る。{org}は功績をたたえ、{name}を{levelLabel}入りとして永く顕彰する。": "{epithet}{name} has stepped away from the ring, and her name is now cut into the {org} Hall of Fame. The {seasons}-season walk belongs not only to one wrestler's record but to the history of the promotion itself.｜{recordLine}｜She has left the ring, but the matches, the words, and the way she carried herself stay in the record and in memory. {org} honors that work and will keep {name} enshrined in the {levelLabel} for good.",
