    "{leader}の権威を認めた。{faction}の外にいる者たちは、一歩引いて見ている。": "You acknowledged {leader}'s authority. The wrestlers outside {faction} are watching from a step back.",
    "{leader}の要求そのものには応じず、{faction}のメンバー一人一人に目を配った。": "You did not grant {leader}'s demand itself, but you looked in on every member of {faction} one by one.",
