    "——ロッカールームの若手が、先輩たちの顔色を窺うようになった。": "—The young ones in the locker room have started reading their seniors' faces.",
    "——蓄積が峠を越えるとステータスは下り坂に入り、引退が視野に入ります。": " — once the buildup carries her past the wall, her stats turn downward and retirement comes into view.",
