    "― {faction}は《{from}》から《{to}》へ気風を変えた ―": "— {faction} changed its character from \"{from}\" to \"{to}\" —",
    "……あいつは、いねえもんとして扱ってる": "...Far as I'm concerned, she isn't there.",
    "……あの方のことは、生涯、許すつもりはございません": "...I have no intention of forgiving that person for as long as I live.",
    "……いなければ、今の自分はいない。だからこそ、倒す": "...Without her, I would not be this. That is exactly why I beat her.",
    "……この三人で、最後まで立てた。それが全部です": "...The three of us stood to the end. That's all it is.",
    "……この借り、必ず返してやる": "...I will pay this back. Count on it.",
    "……どうだ、これが実力の差だ": "...See that? That's the gap between us.",
    "……もう、いいかな。あの人とぶつかり続ける理由も、正直、思い出せないし。": "...I think I'm done. Honestly, I can't even remember why I kept clashing with her.",
    "……もう、ついていけない。": "...I can't follow anymore.",
    "……もう、話し合いでは済まない。あの人とは、リングの上でしか答えが出ない。": "...Talking won't settle this anymore. With her, the only answer is in the ring.",
    "……わかった": "...All right.",
    "……別に気にしてねーし。してねーけど、目に入んだよ": "...Not like I care. I don't, but she keeps ending up in my line of sight.",
    "……同じ場にいるだけで、耐えがたいのです": "...Simply being in the same place as her is more than I can bear.",
    "……失礼ですが、同じ土俵という気にはなれません": "...Forgive me, but I can't think of us as standing on the same ground.",
    "……思い切りましたな。ここまで出す団体は他にありません。": "...Bold move. No other organization pays out this much.",
    "……正直、近くにいられると気が休まりません": "...Honestly, I can't relax with her nearby.",
    "……申し訳ありませんが、お近づきになりたくはありません": "...I'm sorry, but I would rather not get any closer to her.",
    "……覚えてなさいよ。次は絶対に、私が勝つ": "...Remember this. Next time, I win.",
    "…ちょっとわかりません": "...I'm not quite sure.",
    "…今は移籍する気はないわ。": "...I'm not looking to move right now.",
    "…勝負あり。少し噛み合わなかった印象です。": "...And that is the match. It never quite clicked out there.",
    "…挑戦状を叩きつける": "...Throw down a challenge",
    "…見殺し": "...Left her to it",
    "…！？": "…?!",
