    "※ 大会当日までに負傷した場合は自動で補充されます。未確定のまま大会週を迎えた場合はおまかせ編成で出場します。": "※ Anyone injured before the day of the tournament is replaced automatically. If the tournament week arrives with slots unconfirmed, they are filled by auto booking.",
    "※ 翌シーズンまで満額、その後毎年半減。1pt未満で消滅。": "※ Full value through the following season, then halved every year after. It disappears below 1pt.",
