    "※ 閉じた後もロスター閲覧・関係性マップ等は確認できます。<br>※ 週送り（次シーズン進行）はできません。": "※ You can still browse the roster, the relationship map and so on after closing.<br>※ You cannot advance the week or move to the next season.",
