    "勝負あり！手堅くまとめました！": "And that's the match! A solid, no-nonsense finish.",
    "勝負の世界では険悪な関係も時に武器になる。だが限度を超えると組織全体を蝕む。社長が間に立ち、最悪の事態を避ける。成功率は約70%。失敗しても関係はそのまま。": "In this business, a bad relationship can sometimes be a weapon. But past a certain point, it eats away at the whole organization. The president steps in to head off the worst outcome. Success runs around 70%; a failed attempt just leaves things as they were.",
