    "収入の柱はチケット・グッズ・スポンサー・放映料。支出の柱は給与です。選手が育って格が上がれば、給与も上がります。赤字が続けば資金危機に（→ ゲームの目的）。": "Your income rests on tickets, merch, sponsors and broadcast fees. Your outgoings rest on salaries. As wrestlers grow and rise in stature, their pay rises with them. Keep running a deficit and you head for a cash crisis (→ the point of the game).",
