    "団体人気{n}以上で PPV GRAND FINAL への出場資格を獲得できます": "Reach promotion popularity {n} to qualify for the PPV GRAND FINAL",
    "団体人気{pop}以上で交渉可能": "Negotiable at promotion popularity {pop} or above",
    "団体人気が25を突破！ 団体規模の拡大で契約枠に余裕ができました。": "Promotion popularity has passed 25! As the promotion grows, you have more room in your contract slots.",
    "団体人気が30に達すると出場資格を獲得。": "Reach promotion popularity 30 and you qualify. ",
    "団体人気が50を突破！ 主力と若手をより厚く抱えられるようになりました。": "Promotion popularity has passed 50! You can now carry more depth in both your core and your young wrestlers.",
