    "団体人気がある程度育ってから解禁される書類。選手の人気を直接押し上げたいときに。ひとりだけを売り出し続けると、周囲の目が冷たくなる点には留意すること。": "This paper only unlocks once the organization's popularity has grown some. Use it when you want to push one fighter's popularity directly — just note that pushing the same fighter over and over cools the room around her.",
