    "社長命令により、選手が徒党を組むことを禁じています。<br>この通達が続くかぎり、新たな派閥は生まれません。<br>社長室の「派閥解散命令」から、いつでも解くことができます。": "By your order, the wrestlers are forbidden to band together.<br>While the notice stands, no new faction can form.<br>You can lift it at any time from the Faction Disbandment Order in your office.",
