    "赤字が縮小しています！ 人気を上げてスポンサー・放映権収入を増やし、損益分岐点を超えよう。": "The deficit is shrinking! Build popularity to grow sponsor and broadcast income, and push past break-even.",
    "赤字地獄": "Deficit Hell",
    "赤字地獄を乗り越え、ついに安定した黒字経営を達成しました！": "You have come through deficit hell and finally run a steady profit!",
    "赤字縮小": "Narrowing the Gap",
    "起 案": "On the Desk",
    "起案された支給額の中から、いくら積むかを社長が決める。額面が彼女の格に見合ってこそ、誠意は伝わる。安すぎる額は、かえって心を離れさせることもある。": "The president picks how much to pay from a set of proposed amounts. Sincerity only lands when the figure matches her standing — an amount that's too low can push her further away instead.",
