    "通算{reigns}度の戴冠、通算{defenses}度の防衛。その数字は、{name}が団体の中心であり続けた時間の重さを物語る。": "The title column reads {reigns} and the defense column {defenses}. Those numbers carry the weight of the years {name} spent at the center of the promotion.",
    "通算{reigns}度の戴冠。その数字は、{name}が団体の中心であり続けた時間の重さを物語る。": "The title column reads {reigns}. That number carries the weight of the years {name} spent at the center of the promotion.",
