    "関係あり": "Has connections",
    "関係ありのみ": "Connected only",
    "関係が良ければ納得するが、そうでなければ不満が残る": "Accepted if close, resented if not",
    "関係が険悪に沈むと、ロッカーが荒れ、タッグが壊れ、最悪の場合は造反や離脱に至ります。修復の道も残されています——社長室に修復の書類が並ぶことがあります。": "When a relationship sinks into open hostility, the locker room turns, tag teams break, and at worst it ends in revolt or a walkout. There is still a way back — papers to mend it can appear on your desk.",
    "関係を維持。効果なし": "The relationship holds. No effect",
    "関係修復": "Reconciliation",
    "関係修復斡旋書": "Reconciliation Order",
    "関節や首を捕らえて動きを奪い、ギブアップや消耗を狙う。": "Traps a joint or the neck to take her movement away, going for a submission or for the wear.",
    "関節・絞め技": "Locks & Chokes",
    "関節技": "Submission",
    "関節技を決めた！ このまま極めるか！？": "The hold is locked in! Can she keep it on?!",
