    "限界": "At the limit",
    "限界突破": "Limit Break",
    "陥落": "Dethroned",
    "陰り": "Waning",
    "陰りが見え始める…": "A shadow starts to fall…",
    "陰りの見えた選手": "Wrestlers past their peak",
    "険悪": "Hostile",
    "隆盛": "Surging",
    "際立った勲章を持たず、評価の積み上げに苦労している": "No standout honors to speak of, and struggling to build up its rating",
    "隠れた実力派": "The Hidden Talent",
    "隣にいると、居心地がいいのよね……ふふ": "It's comfortable next to her... hehe.",
    "集客 +12%、両リーダー間の因縁が一気に深まる（rivalry 大幅増）。負けた派閥は崩壊リスク": "Attendance +12%, and the grudge between the two leaders deepens sharply (rivalry way up). The losing faction risks falling apart",
    "集客もスポンサーも放映料も、すべての土台です。こちらも高いほど上がりにくく、シーズン末には順位に応じた自然減があります——頂の維持にも努力が要ります。": "Attendance, sponsors, broadcast fees — it is the foundation for all of them. This too gets harder to raise the higher it goes, and at season's end it decays by your standing — staying on top takes work as well.",
    "集客力": "Draw",
    "集客力にボーナス。グッズ売上の重みも増加": "Bonus to draw power. Also boosts the weight of merch income",
